            // 发现链立见新装 shim/版本；同样包后台（发现 + 装饰都可能碰磁盘）
            identity = await Task.Run(() => DecorateIdentity(
                DshWeb.Domain.DshDiscovery.DiscoverCurrentRuntime()), ct);
