    private static PendingUpdate _pendingUpdate;
    private static string _pendingLatest = "";
    private static string? _pendingLocal;
    // ---- 任务五：后台更新构建状态（防误关 + UI 反馈） ----
    // 「构建是否正在跑」与它的取消源都在 Managers/DshUpdateManager（BuildInProgress /
